import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import { ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

import { AuthProvider, useAuth } from './context/AuthContext';

import Navbar from './components/Navbar';
import Footer from './components/Footer';

import MapPage from './components/MapPage';
import ProductsPage from './components/ProductsPage';
import InnovationPage from './components/InnovationPage';
import ArticlesPage from './components/ArticlesPage';
import AdminArticles from './components/AdminArticles';
import AdminDashboard from './components/AdminDashboard';

import Login from './components/Login';
import Register from './components/Register';
import ProtectedRoute from './components/ProtectedRoute';

import './App.css';

// ---------------- HOME PAGE (Bharat Connect Styled) ----------------



// -------------- Home Card Component (for cleaner code) --------------

const HomeCard = ({ to, title, btn, img }) => (
  <Link
    to={to}
    className="bg-[#fffaf1] border border-[#e2d4b5] rounded-2xl shadow-md hover:shadow-xl 
               transition-all duration-300 p-5 hover:-translate-y-1"
  >
    {/* Card Image */}
    <div className="w-full h-32 mb-4 overflow-hidden rounded-xl shadow-sm">
      <img src={img} className="w-full h-full object-cover" alt={title} />
    </div>

    {/* Title */}
    <h3 className="text-xl font-semibold text-[#0e3b3a] text-center mb-3">
      {title}
    </h3>

    {/* Button */}
    <div className="flex justify-center">
      <button className="px-5 py-2 bg-[#b2541a] text-white rounded-lg text-sm 
                         hover:bg-[#8d3c11] transition shadow">
        {btn}
      </button>
    </div>
  </Link>
);


// ---------------------- MAIN APP ------------------------

function App() {
  return (
    <AuthProvider>
      <Router>
        <div className="min-h-screen flex flex-col bg-[#f8f4ec]">

          <Navbar />

          <main className="flex-1">
            <Routes>
              <Route path="/" element={<Home />} />
              <Route path="/map" element={<MapPage />} />
              <Route path="/products" element={<ProductsPage />} />
              <Route path="/innovations" element={<InnovationPage />} />
              <Route path="/articles" element={<ArticlesPage />} />

              <Route path="/login" element={<Login />} />
              <Route path="/register" element={<Register />} />

              {/* Admin Protected Routes */}
              <Route
                path="/admin"
                element={
                  <ProtectedRoute requiredRole="admin">
                    <AdminDashboard />
                  </ProtectedRoute>
                }
              />

              <Route
                path="/admin/articles"
                element={
                  <ProtectedRoute requiredRole="admin">
                    <AdminArticles />
                  </ProtectedRoute>
                }
              />
            </Routes>
          </main>

          <Footer />
        </div>

        <ToastContainer
          position="top-right"
          autoClose={3000}
          hideProgressBar={false}
          newestOnTop
          closeOnClick
          draggable
          pauseOnHover
        />
      </Router>
    </AuthProvider>
  );
}

export default App;
